var SAVEDSET=loadSaved(), savedView=false, draggingMint=null, _dragStartedAt=0;
function savedCount(){return Object.keys(SAVEDSET).length;}
function persistSaved(){try{localStorage.setItem(SAVED_KEY,JSON.stringify(Object.keys(SAVEDSET).slice(0,SAVED_MAX)));}catch(e){}}
