  var more=el('button','fchip'+(anyMore()?' hasdot':'')+(panelOpen?' on':''));more.type='button';more.setAttribute('aria-expanded',panelOpen?'true':'false');
  more.appendChild(document.createTextNode('More'));var dot=el('span','cdot');dot.setAttribute('aria-hidden','true');more.appendChild(dot);
