var _isTouch=false;try{_isTouch=!!(window.matchMedia&&window.matchMedia('(pointer:coarse)').matches);}catch(e){}
function _saveHint(){return _isTouch?'Tap the ★ on a coin to save it.':'Drag a coin over here to save it.';}

function afterSavedChange(mint){updateSavedToggle();var r=document.getElementById('savedRail');if(r&&r.classList.contains('open'))renderSavedRail();updateCardStar(mint);}
function updateCardStar(mint){mint=cleanMint(mint);if(!mint)return;var wall=document.getElementById('wall');if(!wall)return;var cards=wall.querySelectorAll('[data-mint="'+mint+'"]');for(var i=0;i<cards.length;i++){var st=cards[i].querySelector('.star');if(st){var on=isSaved(mint);st.classList.toggle('on',on);st.setAttribute('aria-pressed',on?'true':'false');st.setAttribute('aria-label',(on?'Remove ':'Save ')+(cards[i].getAttribute('data-sym')||'coin')+(on?' from saved':' to saved'));}}}

function savedCard(s){
  var row=el('div','srow');var _m=cleanMint(s.mint);
  row.setAttribute('role','button');row.tabIndex=0;row.setAttribute('aria-label','Open '+dv(s.sym));
  row.appendChild(avatar(s));
  var idw=el('div','sr-idw');idw.appendChild(el('div','sr-sym',dv(s.sym)));
  idw.appendChild(el('div','sr-mult',multStr(multipleOf(s))+' · '+dv(s.mcap)));row.appendChild(idw);
  var rm=el('button','sr-x');rm.type='button';rm.textContent='×';rm.setAttribute('aria-label','Remove '+dv(s.sym)+' from saved');
  rm.addEventListener('click',function(e){e.stopPropagation();if(_m){setSaved(_m,false);afterSavedChange(_m);}});
  row.appendChild(rm);
  function _open(){openDetail(s);}
  row.addEventListener('click',_open);
  row.addEventListener('keydown',function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();_open();}});
  return row;
}
function renderSavedRail(){
  var rail=document.getElementById('savedRail');if(!rail)return;var body=rail.querySelector('.srbody');if(!body)return;body.textContent='';
  var live=[];for(var i=0;i<SIGNALS.length;i++){var s=SIGNALS[i];if(s&&s.mint&&SAVEDSET[cleanMint(s.mint)])live.push(s);}
  if(!savedCount()){body.appendChild(el('div','srempty','No saved coins yet. '+_saveHint()));return;}
  if(!live.length){body.appendChild(el('div','srempty','Your saved coins aren’t live in the feed right now. They’ll show here when they are.'));return;}
  live.forEach(function(s){body.appendChild(savedCard(s));});
}
function updateSavedToggle(){var b=document.getElementById('savedToggle');if(!b)return;b.classList.toggle('on',savedView);b.setAttribute('aria-pressed',savedView?'true':'false');var n=b.querySelector('.n');if(n)n.textContent='('+savedCount()+')';}
function openSavedRail(){var r=document.getElementById('savedRail');if(r)r.classList.add('open');}
function closeSavedRail(){var r=document.getElementById('savedRail');if(r)r.classList.remove('open');}
function setSavedView(on){savedView=on;if(savedView){openSavedRail();renderSavedRail();}else{closeSavedRail();}updateSavedToggle();}
function toggleSavedView(){setSavedView(!savedView);}
function railDragOpen(on){var r=document.getElementById('savedRail');if(!r)return;if(on){r.classList.add('open','dropping');renderSavedRail();}else{r.classList.remove('dropping');if(!savedView)r.classList.remove('open');}}
function syncSaved(){updateSavedToggle();var r=document.getElementById('savedRail');if(r&&r.classList.contains('open'))renderSavedRail();}
function clearAllSaved(){if(savedCount()&&(typeof confirm==='function')&&!confirm('Remove all '+savedCount()+' saved coins?'))return;SAVEDSET={};persistSaved();updateSavedToggle();renderSavedRail();var st=document.querySelectorAll('#wall .star.on');for(var i=0;i<st.length;i++){st[i].classList.remove('on');st[i].setAttribute('aria-pressed','false');}}
function doRefresh(btn){if(btn){btn.classList.add('spin');btn.disabled=true;}try{refreshFeed();}catch(e){}setTimeout(function(){if(btn){btn.classList.remove('spin');btn.disabled=false;}},800);}
function refreshCard(btn){if(!currentSignal||!currentSignal.mint)return;var m=cleanMint(currentSignal.mint);if(btn){btn.classList.add('spin');btn.disabled=true;}var done=function(){if(btn){setTimeout(function(){btn.classList.remove('spin');if(btn.parentNode)btn.disabled=false;},800);}};try{fetch("/api/app2/feed?gated=1&t="+Date.now(),{cache:"no-store",headers:{"Accept":"application/json"}}).then(function(r){return r.ok?r.json():null;}).then(function(d){if(Array.isArray(d)&&d.length){_pqFeedGoodT=Date.now();SIGNALS=d;var _c=document.getElementById("count");if(_c)_c.textContent=String(SIGNALS.length);var _u=document.getElementById("upd");if(_u)_u.textContent="· updated "+_stamp();applyFilters();var found=null;for(var i=0;i<SIGNALS.length;i++){if(SIGNALS[i]&&cleanMint(SIGNALS[i].mint)===m){found=SIGNALS[i];break;}}if(found&&!overlay.hidden&&currentSignal&&cleanMint(currentSignal.mint)===m){currentSignal=found;buildDetail(found);var nb=modal.querySelector('.m-refresh');if(nb)nb.focus();}else _pqStarterRebind();}done();},function(){done();});}catch(e){done();}}

 
(function(){
  var bar=el('div');bar.id='savedbar';
  var btn=el('button','savedToggle');btn.type='button';btn.id='savedToggle';btn.setAttribute('aria-pressed','false');btn.setAttribute('aria-label','Show your saved coins');
  var stx=el('span','st');stx.setAttribute('aria-hidden','true');stx.textContent='★';btn.appendChild(stx);
  btn.appendChild(document.createTextNode('Saved'));
  btn.addEventListener('click',function(e){e.stopPropagation();toggleSavedView();});
  bar.appendChild(btn);
  var rfr=el('button','refreshBtn');rfr.type='button';rfr.setAttribute('aria-label','Refresh coins now');var rfi=el('span','ri');rfi.setAttribute('aria-hidden','true');rfi.textContent='↻';rfr.appendChild(rfi);rfr.appendChild(document.createTextNode(' Refresh'));rfr.addEventListener('click',function(e){e.stopPropagation();doRefresh(rfr);});
  bar.appendChild(rfr);
  var pt=document.getElementById('pqtrio');if(pt){pt.appendChild(bar);}else{var wall=document.getElementById('wall');if(wall&&wall.parentNode){wall.parentNode.insertBefore(bar,wall);}else{var w=document.querySelector('.wrap');if(w)w.appendChild(bar);}}

  var rail=el('aside');rail.id='savedRail';rail.setAttribute('aria-label','Saved coins');
  var head=el('div','srhead');var title=el('div','srtitle');var t1=el('span','st');t1.setAttribute('aria-hidden','true');t1.textContent='★';title.appendChild(t1);title.appendChild(document.createTextNode('Saved'));head.appendChild(title);
  var clr=el('button','srclear');clr.type='button';clr.textContent='Clear all';clr.setAttribute('aria-label','Clear all saved coins');clr.addEventListener('click',function(e){e.stopPropagation();clearAllSaved();});
  var close=el('button','srclose');close.type='button';close.textContent='×';close.setAttribute('aria-label','Close saved');close.addEventListener('click',function(e){e.stopPropagation();setSavedView(false);});
  var hact=el('div','srhead-actions');hact.appendChild(clr);hact.appendChild(close);head.appendChild(hact);
  rail.appendChild(head);rail.appendChild(el('div','srbody'));document.body.appendChild(rail);

  rail.addEventListener('dragover',function(e){e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy';});
  rail.addEventListener('drop',function(e){e.preventDefault();var m=draggingMint;try{if(!m&&e.dataTransfer)m=cleanMint(e.dataTransfer.getData('text/plain'));}catch(_e){}if(m){setSaved(m,true);afterSavedChange(m);}});
   
  document.addEventListener('dragend',function(){draggingMint=null;railDragOpen(false);var ds=document.querySelectorAll('.tk.dragging');for(var i=0;i<ds.length;i++)ds[i].classList.remove('dragging');});
})();
 

function glanceCard(s,i,initial){
  var mult=multipleOf(s), faded=ceDone(s), up=!faded&&(Number(s.pct)||0)>=0;
  var card=el("button","tk");card.type="button";
  
  var _sm=cleanMint(s.mint);if(_sm){card.setAttribute("data-mint",_sm);card.setAttribute("data-sym",dv(s.sym));}
  card.draggable=true;
  card.addEventListener("dragstart",function(e){try{if(!_sm)return;draggingMint=_sm;_dragStartedAt=Date.now();if(e.dataTransfer){e.dataTransfer.setData("text/plain",_sm);e.dataTransfer.effectAllowed="copy";}card.classList.add("dragging");railDragOpen(true);}catch(_e){}});
  card.addEventListener("dragend",function(){draggingMint=null;card.classList.remove("dragging");railDragOpen(false);});
  card.setAttribute("aria-label",s.sym+", "+multStr(mult)+", "+dv(s.mcap)+" market cap, flagged "+dv(s.age)+" ago."+(s.feeRug===true?" Warning: fake or bundled volume.":(s.feeRugFlicker===true?" Warning: fake volume coming and going.":""))+((s.realCrowd&&s.realCrowd.padded===true)?" Warning: padded holder count.":"")+(s.dexPaid===true?" DEX paid.":"")+" Open details.");
  if(initial){card.style.animationDelay=Math.min(i*8,360)+"ms";}else{card.style.animation="none";}
  var sp=sparkSvg(sparkPts(1,chartEnd(mult,faded),seedFrom(String(s.sym)+String(s.mint))),100,40,faded?DOWN_HEX:'#34D3E6',false);sp.setAttribute("class","spark-bg");card.appendChild(sp);
  card.appendChild(avatar(s));
  var idw=el("div","idw");
  idw.appendChild(el("div","sym",dv(s.sym)));
  if(s.stacked===true&&!faded&&s.feeRug!==true&&!(s.realCrowd&&s.realCrowd.padded===true)){var _cvs=el("span","cvstar","★");_cvs.setAttribute("aria-hidden","true");var _sy=idw.querySelector(".sym");if(_sy){_sy.insertBefore(_cvs,_sy.firstChild);}}
  var _pad=(s.realCrowd&&s.realCrowd.padded===true);
  var _fvo=(s.feeRug!==true&&s.feeRugFlicker===true);    
  if(s.feeRug===true||_fvo||s.dexPaid===true||_pad){var nrow=el("div","namerow nr-"+(s.feeRug===true||_fvo?"f":"")+(_pad?"p":"")+(s.dexPaid===true?"d":""));if(s.feeRug===true||_fvo){var fw=el("div",_fvo?"frug fl":"frug");fw.appendChild(el("span","fdot"));fw.appendChild(el("span","tgw","fake volume"));fw.appendChild(el("span","tgs","fake"));fw.setAttribute("aria-hidden","true");nrow.appendChild(fw);}if(_pad){var pw=el("div","frug");pw.appendChild(el("span","fdot"));pw.appendChild(el("span","tgw","padded crowd"));pw.appendChild(el("span","tgs","padded"));pw.setAttribute("aria-hidden","true");nrow.appendChild(pw);}if(s.dexPaid===true){var dw=el("div","dexp");dw.appendChild(el("span","ddot"));dw.appendChild(el("span","tgw","DEX paid"));dw.appendChild(el("span","tgs","DEX"));dw.setAttribute("aria-hidden","true");nrow.appendChild(dw);}nrow.appendChild(el("div","name",dv(s.name)));idw.appendChild(nrow);}else{idw.appendChild(el("div","name",dv(s.name)));}    
  var mw=el("div","mw");mw.appendChild(el("div",multCls(mult,up,faded),multStr(mult)));mw.appendChild(el("div","gl",dv(s.mcap)+" · "+dv(s.age)+" ago"));
  var chev=el("span","chev");chev.setAttribute("aria-hidden","true");chev.innerHTML=IC.chev;
  card.appendChild(idw);card.appendChild(mw);card.appendChild(chev);
  var _on=isSaved(_sm);var star=el("span","star"+(_on?" on":""));star.setAttribute("role","button");star.tabIndex=0;star.textContent="★";
  star.setAttribute("aria-pressed",_on?"true":"false");star.setAttribute("aria-label",(_on?"Remove ":"Save ")+dv(s.sym)+(_on?" from saved":" to saved"));
  function _toggleStar(e){e.stopPropagation();e.preventDefault();if(_sm){toggleSaved(_sm);afterSavedChange(_sm);}}
  star.addEventListener("click",_toggleStar);
  star.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){_toggleStar(e);}});
  card.appendChild(star);
  card.addEventListener("click",function(){openDetail(s);});
  return card;
}

var overlay=document.getElementById("overlay"), modal=document.getElementById("modal"), lastFocused=null;
var CE_STEP_LABEL={flagged:"Flagged",heating:"Early",strong:"Building",confirmed:"Peak"};


function buildClearEyes(s){
  if(!s||(!s.ceStep&&s.bail!==true))return null;
  var bail=(s.bail===true);
  var dead=(!bail&&s.ceStep==="fading"), cool=(!bail&&s.ceStep==="cooling"), floored=(!bail&&s.ceStep==="floor"), early=(!bail&&s.ceStep==="early");
  var box=el("div","ce"+((bail||dead)?" dead":cool?" cooling":floored?" floor":early?" early":""));
  var hd=el("div","ce-hd");
  hd.appendChild(el("span","ce-name","CLEAR EYES"));
  hd.appendChild(el("span","ce-sub","how strong it's gotten"));
  var q=el("button","ce-q","?");q.type="button";q.setAttribute("aria-label","What is Clear Eyes?");q.setAttribute("aria-expanded","false");q.setAttribute("aria-controls","ce-help");
  hd.appendChild(q);box.appendChild(hd);
  var lad=el("div","ce-lad");
  if(bail||dead||cool||floored||early){
    lad.setAttribute("role","img");
    if(bail){lad.setAttribute("aria-label","Rug risk — bail out");lad.appendChild(el("span","ce-step dead-step","⚠ Rug risk"));}
    else if(dead){lad.setAttribute("aria-label","Faded — this coin is dead");lad.appendChild(el("span","ce-step dead-step","Faded"));}
    else if(cool){lad.setAttribute("aria-label","Pulled back below the flag");lad.appendChild(el("span","ce-step cool-step","Pulled back"));}
    else if(early){lad.setAttribute("aria-label","Early — a fresh call, still holding");lad.appendChild(el("span","ce-step early-step","Early"));}
     
    else{lad.setAttribute("aria-label","Warning — under $15k market cap");lad.appendChild(el("span","ce-step floor-step","⚠ Under $15k"));}
  }else{
    var idx=(typeof s.ceStepIndex==="number")?s.ceStepIndex:0;
    lad.setAttribute("role","img");lad.setAttribute("aria-label","Strength: "+(CE_STEP_LABEL[s.ceStep]||s.ceStep)+", step "+(idx+1)+" of 4");
    ["flagged","heating","strong","confirmed"].forEach(function(k,i){
      if(i>0)lad.appendChild(el("span","ce-conn"+(i<=idx?" on":"")));
      lad.appendChild(el("span","ce-step"+(i===idx?" on":"")+(i<idx?" past":""),CE_STEP_LABEL[k]));
    });
  }
  box.appendChild(lad);
  if(s.ceLine)box.appendChild(el("div","ce-line",s.ceLine));
  var help=el("div","ce-help");help.hidden=true;help.id="ce-help";help.setAttribute("role","region");help.setAttribute("aria-label","How Clear Eyes works");
  help.textContent="We watch every coin after it's flagged. As buyers and price back it, it climbs: Flagged → Early → Building → Peak. If it dies, it shows Faded.";
  box.appendChild(help);
  q.addEventListener("click",function(){var h=help.hidden;help.hidden=!h;q.setAttribute("aria-expanded",h?"true":"false");});
  return box;
}


function buildHolders(s){
  var h=s&&s.topHolders;if(!h)return null;
  var list=Array.isArray(h.list)?h.list:[];
  if(!list.length&&!h.whales&&!h.smart&&h.top1==null)return null;
  var box=el("div","th");
  var hd=el("div","th-hd");hd.appendChild(el("span","th-name","Top Holders"));hd.appendChild(el("span","th-sub","known wallets in this coin"));box.appendChild(hd);
  for(var i=0;i<list.length&&i<5;i++){var it=list[i];if(!it||it.name==null)continue;
    var row=el("div","th-row");row.appendChild(el("span","th-lab",String(it.name)));
    var pct=(it.pct==null)?"—":(Math.round(Number(it.pct)*10)/10)+"%";
    row.appendChild(el("span","th-pct",pct));box.appendChild(row);}
  var parts=[];
  if(h.whales)parts.push(h.whales+(h.whales===1?" whale":" whales"));
  if(h.smart)parts.push(h.smart+" smart-money");
  if(h.top1!=null)parts.push("biggest "+(Math.round(Number(h.top1)*10)/10)+"%");
  if(parts.length)box.appendChild(el("div","th-ft",parts.join("  ·  ")));
  return box;
}
 
function buildRealCrowd(s){
  var rc=s&&s.realCrowd;if(!rc||rc.real==null||rc.shown==null)return null;
  var padded=(rc.tier==="padded");
  var box=el("div","ce"+(padded?" pad":""));
  var hd=el("div","ce-hd");
  hd.appendChild(el("span","ce-name","REAL CROWD"));
  hd.appendChild(el("span","ce-sub","who actually holds this"));
  var q=el("button","ce-q","?");q.type="button";q.setAttribute("aria-label","What is Real Crowd?");q.setAttribute("aria-expanded","false");q.setAttribute("aria-controls","rc-help");
  hd.appendChild(q);box.appendChild(hd);
  var pct=Math.max(0,Math.min(100,Number(rc.pct)||0));
  var bar=el("div","rc-bar");var fill=el("i");fill.style.width=pct+"%";
  fill.className=padded?"pad":(rc.tier==="clean")?"ok":"mid";
  bar.appendChild(fill);bar.setAttribute("role","img");bar.setAttribute("aria-label",pct+" percent of the shown holders are real");
  box.appendChild(bar);
  var nums=el("div","rc-nums");
  nums.appendChild(el("b",null,Number(rc.real).toLocaleString()+" real"));
  nums.appendChild(document.createTextNode("  ·  "));
  nums.appendChild(el("span","sh",Number(rc.shown).toLocaleString()+" shown"));
  box.appendChild(nums);
  if(rc.line)box.appendChild(el("div","ce-line",rc.line));
  var help=el("div","ce-help");help.hidden=true;help.id="rc-help";help.setAttribute("role","region");help.setAttribute("aria-label","How Real Crowd works");
  help.textContent="“Shown” is the holder count the coin advertises. “Real” is how many wallets actually hold a meaningful amount right now — the rest hold dust (near-zero). A big gap means the crowd is padded.";
  box.appendChild(help);
  q.addEventListener("click",function(){var h=help.hidden;help.hidden=!h;q.setAttribute("aria-expanded",h?"true":"false");});
  return box;
}
function buildDetail(s){
  var mult=multipleOf(s), faded=ceDone(s), up=!faded&&(Number(s.pct)||0)>=0, mint=cleanMint(s.mint), soc=s.socials||{};
  modal.textContent="";
  
  var head=el("div","m-head");head.appendChild(avatar(s));
  var tw=el("div","m-title");var sym=el("div","sym",dv(s.sym));sym.id="mTitle";tw.appendChild(sym);tw.appendChild(el("div","name",dv(s.name)));
  var mw=el("div","m-mw");mw.appendChild(el("div",multCls(mult,up,faded),multStr(mult)));mw.appendChild(el("div","flag","flagged "+dv(s.age)+" ago"));
  var close=el("button","close","×");close.type="button";close.setAttribute("aria-label","Close");close.addEventListener("click",closeDetail);
  var mrf=el("button","m-refresh");mrf.type="button";mrf.setAttribute("aria-label","Refresh this coin's data");var mri=el("span","ri");mri.setAttribute("aria-hidden","true");mri.textContent="↻";mrf.appendChild(mri);mrf.addEventListener("click",function(e){e.stopPropagation();refreshCard(mrf);});
  head.appendChild(tw);head.appendChild(mw);head.appendChild(mrf);head.appendChild(close);

  var spark=el("div","m-spark");spark.appendChild(sparkSvg(sparkPts(1,chartEnd(mult,faded),seedFrom(String(s.sym)+String(s.mint))),300,52,faded?DOWN_HEX:'#34D3E6',true));
  spark.appendChild(el("span","lab","since flagged"));

  var sub=el("div","m-sub");sub.appendChild(el("span","tag","SOL"));
  if(s.feeRug===true){var mfr=el("span","frug");mfr.appendChild(el("span","fdot"));mfr.appendChild(document.createTextNode("fake volume"));mfr.setAttribute("role","note");mfr.setAttribute("aria-label","Warning: fake or bundled volume");sub.appendChild(mfr);}else if(s.feeRugFlicker===true){var mfo=el("span","frug fl");mfo.appendChild(el("span","fdot"));mfo.appendChild(document.createTextNode("fake volume"));mfo.setAttribute("role","note");mfo.setAttribute("aria-label","Warning: fake volume coming and going");sub.appendChild(mfo);}
  if(s.realCrowd&&s.realCrowd.padded===true){var mpc=el("span","frug");mpc.appendChild(el("span","fdot"));mpc.appendChild(document.createTextNode("padded crowd"));mpc.setAttribute("role","note");mpc.setAttribute("aria-label","Warning: padded holder count, most holders hold dust");sub.appendChild(mpc);}
  if(s.dexPaid===true){var mdp=el("span","dexp");mdp.appendChild(el("span","ddot"));mdp.appendChild(document.createTextNode("DEX paid"));mdp.setAttribute("role","note");mdp.setAttribute("aria-label","DEX paid");sub.appendChild(mdp);}
  var fm=el("span","fm");fm.appendChild(el("b",null,"flag "));fm.appendChild(document.createTextNode(dv(s.flagMc)));sub.appendChild(fm);
  if(mint){var ca=el("button","ca");ca.type="button";ca.innerHTML=IC.copy;ca.appendChild(document.createTextNode(shortMint(mint)));
    ca.setAttribute("aria-label","Copy contract address");
    ca.addEventListener("click",function(){try{navigator.clipboard.writeText(mint);ca.lastChild.textContent="copied";setTimeout(function(){ca.lastChild.textContent=shortMint(mint);},1100);}catch(e){}});
    sub.appendChild(ca);}

  var grid=el("div","grid");
  grid.appendChild(cell("Mkt cap",s.mcap));grid.appendChild(cell("Liquidity",s.liq));grid.appendChild(cell("Holders",s.holdersCount));
  grid.appendChild(cell("Txns 5m",s.txns5m));grid.appendChild(cell("Top 10",s.top10));
  grid.appendChild(cell("Bundles",s.bundles));grid.appendChild(cell("Snipers",s.snipers));grid.appendChild(cell("Vol 5m",s.vol5m));
  grid.appendChild(cell("Vol 1h",s.vol1h));grid.appendChild(cell("Vol 24h",s.vol24h));
  [0,5].forEach(function(r0){var cs=grid.querySelectorAll(".cell"),mx=0,j;for(j=r0;j<r0+5&&j<cs.length;j++)mx=Math.max(mx,cs[j].querySelector(".v").textContent.length);if(mx>=10)for(j=r0;j<r0+5&&j<cs.length;j++)cs[j].classList.add(mx>=12?"gt3":mx===11?"gt2":"gt1");});    

  var act=el("div","act");
  if(mint){act.appendChild(link("ic","https://dexscreener.com/solana/"+mint,IC.chart,"Chart on Dexscreener"));
    act.appendChild(link("ic","https://x.com/search?q="+mint+"&f=live",IC.x,"Search on X"));}
  if(safeUrl(soc.x))act.appendChild(link("ic",safeUrl(soc.x),IC.x,"Token X / Twitter"));
  if(safeUrl(soc.tg))act.appendChild(link("ic",safeUrl(soc.tg),IC.tg,"Token Telegram"));
  if(safeUrl(soc.web))act.appendChild(link("ic",safeUrl(soc.web),IC.web,"Token website"));
  if(mint){var buy=link("buy",buyUrl(mint),IC.buy,"Buy on "+PLATFORMS[PLAT].n);buy.insertBefore(document.createTextNode("Buy on "+PLATFORMS[PLAT].n),buy.firstChild);act.appendChild(buy);}
  modal.appendChild(head);modal.appendChild(spark);modal.appendChild(sub);
  var _ce=buildClearEyes(s);if(_ce)modal.appendChild(_ce);
  var _rcbox=buildRealCrowd(s);if(_rcbox)modal.appendChild(_rcbox);
  modal.appendChild(grid);var _th=buildHolders(s);if(_th)modal.appendChild(_th);modal.appendChild(act);
}
function _focusables(){return modal.querySelectorAll('a[href],button:not([disabled])');}
function _onKey(e){if(e.key==="Escape"){e.preventDefault();closeDetail();return;}
  if(e.key==="Tab"){var f=_focusables();if(!f.length)return;var first=f[0],last=f[f.length-1];
    if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
    else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
function openDetail(s){currentSignal=s;lastFocused=document.activeElement;buildDetail(s);overlay.hidden=false;document.body.style.overflow="hidden";
  document.addEventListener("keydown",_onKey,true);var c=modal.querySelector(".close");if(c)c.focus();}
function closeDetail(){overlay.hidden=true;document.body.style.overflow="";document.removeEventListener("keydown",_onKey,true);
  if(lastFocused&&lastFocused.focus)lastFocused.focus();}
