function setSaved(m,on){m=cleanMint(m);if(!m)return;if(on){if(!SAVEDSET[m]&&savedCount()>=SAVED_MAX)return;SAVEDSET[m]=true;}else{delete SAVEDSET[m];}persistSaved();}
