var FSTATE={}, panelOpen=false;

function fActive(f){var st=FSTATE[f.id];return f.type==='toggle'?st===true:(typeof st==='number');}
function anyActive(){return LEAD.concat(MORE).some(fActive);}
function anyMore(){return MORE.some(fActive);}
function passes(s){for(var id in FSTATE){var f=ALLF[id];if(!f||!fActive(f))continue;
  if(f.type==='toggle'){if(!f.test(s))return false;}else if(!f.test(s,f.opts[FSTATE[id]][1]))return false;}return true;}
