(function(){
  var c=document.getElementById('sig-net');if(!c)return;var ctx=c.getContext('2d');
  var W,H,mx=-9999,my=-9999,RADIUS=180,LINK_DIST=130,nodes=[],N=60;
  var COLORS=[[210,225,240],[77,168,232],[59,125,216],[77,232,176]];
  var reduce=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  function resize(){W=c.width=window.innerWidth;H=c.height=window.innerHeight;}
  function scatter(){nodes=[];for(var i=0;i<N;i++){var col=COLORS[Math.floor(Math.random()*COLORS.length)];
    var sp=0.15+Math.random()*0.3,ang=Math.random()*Math.PI*2;
    nodes.push({x:Math.random()*W,y:Math.random()*H,vx:Math.cos(ang)*sp,vy:Math.sin(ang)*sp,bright:0,ping:0,r:col[0],g:col[1],b:col[2]});}}
  resize();scatter();
  window.addEventListener('resize',function(){resize();scatter();});
  document.addEventListener('mousemove',function(e){mx=e.clientX;my=e.clientY;});
  document.addEventListener('mouseleave',function(){mx=-9999;my=-9999;});
  function draw(){
    if(!reduce)requestAnimationFrame(draw);
    ctx.clearRect(0,0,W,H);
    for(var i=0;i<N;i++){var n=nodes[i];n.x+=n.vx;n.y+=n.vy;
      if(n.x<0){n.x=0;n.vx*=-1;}if(n.x>W){n.x=W;n.vx*=-1;}if(n.y<0){n.y=0;n.vy*=-1;}if(n.y>H){n.y=H;n.vy*=-1;}
      var dx=mx-n.x,dy=my-n.y,dist=Math.sqrt(dx*dx+dy*dy),target=dist<RADIUS?1-(dist/RADIUS):0;n.bright+=(target-n.bright)*0.08;}
    for(var i=0;i<N;i++){for(var j=i+1;j<N;j++){var a=nodes[i],b=nodes[j];if(a.bright<0.05&&b.bright<0.05)continue;
      var dx=a.x-b.x,dy=a.y-b.y,dist=Math.sqrt(dx*dx+dy*dy);if(dist>LINK_DIST)continue;
      var st=a.bright>b.bright?a:b,lt=st.bright,lr=Math.round(255+(st.r-255)*lt),lg=Math.round(255+(st.g-255)*lt),lb=Math.round(255+(st.b-255)*lt);
      var strength=Math.min(a.bright,b.bright)*(1-dist/LINK_DIST);
      ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle='rgba('+lr+','+lg+','+lb+','+(strength*0.55).toFixed(3)+')';ctx.lineWidth=1;ctx.stroke();}}
    for(var i=0;i<N;i++){var n=nodes[i],t=n.bright,dr=Math.round(255+(n.r-255)*t),dg=Math.round(255+(n.g-255)*t),db=Math.round(255+(n.b-255)*t),dotR=1.5+t*1.5,alpha=0.15+t*0.85;
      ctx.beginPath();ctx.arc(n.x,n.y,dotR,0,Math.PI*2);ctx.fillStyle='rgba('+dr+','+dg+','+db+','+alpha.toFixed(3)+')';ctx.fill();
      if(t>0.1){ctx.beginPath();ctx.arc(n.x,n.y,dotR+4+t*8,0,Math.PI*2);ctx.fillStyle='rgba('+n.r+','+n.g+','+n.b+','+(t*0.35).toFixed(3)+')';ctx.fill();
        n.ping+=0.008;if(n.ping>1)n.ping=0;
        for(var pp=0;pp<3;pp++){var phase=(n.ping+pp*0.33)%1,radius=3+phase*22,fa=n.bright*0.6*(1-phase);if(fa<0.01)continue;
          ctx.beginPath();ctx.arc(n.x,n.y,radius,0,Math.PI*2);ctx.strokeStyle='rgba('+n.r+','+n.g+','+n.b+','+fa.toFixed(3)+')';ctx.lineWidth=1.2-phase*0.7;ctx.stroke();}}else{n.ping=0;}}
  }
  draw();
})();
