  if (a.dex !== b.dex) out.push(b.dex ? 'dex_on' : 'dex_off')
  if (gated && a.padded !== b.padded) out.push(b.padded ? 'pad_on' : 'pad_off')
  if (gated && b.ce && a.ce !== b.ce && LIVE_CE_KEYS.has(b.ce)) out.push('ce_' + b.ce)
  return out
